import {
  BaseSheet,
  FillRangeOperation,
  InsertColOperation,
  Operation,
  RemoveColOperation,
  Sheet,
  UpdateCellOperation,
} from '@bzl/sheet-js';
import { initialDoc } from '../utils';
import { SheetOTType } from '../../src';
import { describe, expect, beforeEach, test, afterEach } from 'vitest';

describe('left side to insert-col, right side to:', () => {
  let doc1: Omit<BaseSheet, 'apply'>;
  let doc2: Omit<BaseSheet, 'apply'>;
  const op1: InsertColOperation = {
    type: 'insert-col',
    at: 1,
    count: 2,
    id: '1',
  };
  let op2: Operation;

  beforeEach(() => {
    doc1 = initialDoc() as Sheet;
    doc2 = initialDoc() as Sheet;
  });

  afterEach(() => {
    const [op12, op21] = SheetOTType.xTransformMxN([op1], [op2], 'left');
    console.log('op12,', op12);
    console.log('op21,', op21);

    doc1 = SheetOTType.apply(SheetOTType.apply({} as BaseSheet, op1) as BaseSheet, op21);
    doc2 = SheetOTType.apply(SheetOTType.apply({} as BaseSheet, op2) as BaseSheet, op12);
    console.log('doc1,', doc1);
    console.log('doc2,', doc2);
    expect(doc1).toStrictEqual(doc2);
  });

  describe('update-cell', () => {
    test('at before', () => {
      op2 = {
        type: 'update-cell',
        at: [0, op1.at - 1],
        newV: null,
        oldV: {
          value: 2,
        },
        id: '1',
      } as UpdateCellOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'update-cell',
        at: [0, op1.at + 1],
        newV: null,
        oldV: {
          value: 2,
        },
        id: '1',
      } as UpdateCellOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'update-cell',
        at: [0, op1.at],
        newV: null,
        oldV: {
          value: 2,
        },
        id: '1',
      } as UpdateCellOperation;
    });
  });

  describe('insert-col', () => {
    test('at before', () => {
      op2 = {
        type: 'insert-col',
        at: op1.at - 1,
        count: 2,
        id: '1',
      } as InsertColOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'insert-col',
        at: op1.at + 1,
        count: 2,
        id: '1',
      } as InsertColOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'insert-col',
        at: op1.at,
        count: 2,
        id: '1',
      } as InsertColOperation;
    });
  });

  describe('remove-col', () => {
    test('at before', () => {
      op2 = {
        type: 'remove-col',
        at: op1.at - 1,
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
    test('at before without intersection', () => {
      op2 = {
        type: 'remove-col',
        at: op1.at - 1,
        count: 1,
        id: '1',
      } as RemoveColOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'remove-col',
        at: op1.at + 1,
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });

    test('at same', () => {
      op2 = {
        type: 'remove-col',
        at: op1.at,
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
  });

  describe('fill-range', () => {
    test('at before', () => {
      op2 = {
        type: 'fill-range',
        range: [op1.at - 1, 1, op1.at - 1, 2],
        fillBy: 'style',
        style: {
          background: '#FAE1EB',
        },
        id: '1',
      } as FillRangeOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'fill-range',
        range: [op1.at + 1, 1, op1.at + 2, 2],
        fillBy: 'style',
        style: {
          background: '#FAE1EB',
        },
        id: '1',
      } as FillRangeOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'fill-range',
        range: [op1.at, 1, op1.at + 2, 2],
        fillBy: 'style',
        style: {
          background: '#FAE1EB',
        },
        id: '1',
      } as FillRangeOperation;
    });
  });

  // describe('resize-col', () => {
  //   test('at before', () => {
  //     op2 = {
  //       type: 'resize-col',
  //       at: op1.at - 1,
  //       value: 100,
  //       id: '1',
  //     } as ResizeColOperation;
  //   });
  //   test('at after', () => {
  //     op2 = {
  //       type: 'resize-col',
  //       at: op1.at + 1,
  //       value: 100,
  //       id: '1',
  //     } as ResizeColOperation;
  //   });
  //   test('at same', () => {
  //     op2 = {
  //       type: 'resize-col',
  //       at: op1.at,
  //       value: 100,
  //       id: '1',
  //     } as ResizeColOperation;
  //   });
  // });
});
